    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題以生活選擇、資源限制、公共分配與資料比較考查經濟推理；本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u, t, l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」以及目標、資源、數量、時間、使用規則與受影響者。", f"整理限制：分開欲望、可用資源、稀少性、替代方案與尚待查證資料；本題核心是「{explanation}」", f"核對正解：選項 {aid}「{answer}」能用題幹資料說明為何必須選擇。", "排除誘答：找出把免費等同無限、把價格當成唯一原因、把公共提供當成沒有成本或把努力當成能消除限制的說法。", "結論回查：確認答案有回到實際供給、使用競爭、時間成本與分配效果，而非只重複口號。"]
    return {"id": f"question-social-content-civ-bl-iv-1-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-civ-bl-iv-1"], "difficulty": "medium", "answer": {"value": aid, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "國立卓蘭高中附設國中部公開社會課程計畫；本題只研究公開試題與課程評量的能力結構。", "authoringNote": "依官方課綱、單元 KG、三個公立學校公開來源的題型方向，獨立改寫稀少性、欲望與資源、經濟財、財貨與勞務、時間、家庭、企業、政府與公共資源；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-civ-bl-iv-1", "examPatternRefs": refs, "solutionStrategy": "先區分目標與有限資源，確認供給與使用限制，再找出替代方案、受影響者與資料缺口，最後說明為何必須取捨。", "solutionSteps": steps}

